const now = new Date();
const hour = now.getHours();
const minute = now.getMinutes();
const day = now.getDay();

const isWeekday = day >= 1 && day <= 5;
const isMarketHours = (hour > 9 || (hour === 9 && minute >= 15)) && hour < 15.5;
const canTrade = isWeekday && isMarketHours;

return [{
  canProceed: canTrade,
  currentSession: hour < 10 ? 'OPENING' : hour < 12 ? 'MORNING' : hour < 14 ? 'AFTERNOON' : 'CLOSING',
  marketPhase: canTrade ? 'ACTIVE' : 'CLOSED',
  timestamp: now.toISOString()
}];

