        "value": number,
        "interpretation": "BULLISH|BEARISH|NEUTRAL"
      },
      {
        "indicator": "VOLUME_ANALYSIS", 
        "value": "HIGH|NORMAL|LOW",
        "interpretation": "BULLISH|BEARISH|NEUTRAL"
